insert into public.opportunities (id, title, org, descr, category, mode, cost, grade, eligibility, deadline, featured, published, url, tags, last_verified) values
('isef', 'Regeneron ISEF', 'Society for Science', 'The world’s largest international pre-college science competition. Finalists are judged by doctoral-level scientists. The finals are held in a host city each year, and a virtual fair lets people view projects.', 'Competitions', 'In person', 'Not stated', 'High school students (grades not stated)', 'Students qualify by winning at a Society-affiliated local, regional, state or national science fair.', null, true, true, 'https://www.societyforscience.org/isef/', array['science','research']::text[], '2026-10-11'),
('rsi', 'Research Science Institute (RSI)', 'Center for Excellence in Education', 'A summer science and engineering program that pairs on-campus STEM classes with a five-week research internship under expert mentors. Held at MIT, and for 2027 it expands to Stanford for 50 scholars.', 'Research', 'In person', 'Free', 'High school juniors (seniors are not eligible)', 'High school juniors. The page states the program is cost-free to students.', 'Dec 11, 2026, 11:59pm (RSI 2027)', true, true, 'https://www.cee.org/research-science-institute', array['research','science']::text[], '2026-10-11'),
('primes', 'MIT PRIMES', 'MIT Mathematics', 'A year-long research program in mathematics, engineering and science for high school students, with four sections. The page describes all sections as free.', 'Research', 'Hybrid', 'Free', 'Grades 10-11 (sophomores and juniors)', 'MIT PRIMES is for Greater Boston students (in person). PRIMES-USA is for students elsewhere in the U.S. (remote). Yulia’s Dream is for students from Ukraine. Check the official page for who can apply.', 'Nov 2, 2026 (PRIMES, PRIMES-USA, PRIMES Circle)', false, true, 'https://math.mit.edu/research/highschool/primes/', array['math','research','science']::text[], '2026-10-11'),
('cs50x', 'CS50x: Intro to Computer Science', 'Harvard University', 'Harvard’s introductory computer science course: computational thinking, algorithms and data structures, starting in C and moving through Python, SQL and web programming before a final project.', 'Courses', 'Online', 'Free', 'Anyone, with or without programming experience', 'Open to everyone. Submitting problem sets for feedback requires an edX account. Costs of optional certificates are not stated on the page.', null, false, true, 'https://cs50.harvard.edu/x/', array['coding']::text[], '2026-10-11'),
('ocw', 'MIT OpenCourseWare', 'Massachusetts Institute of Technology', 'A free web publication of virtually all MIT course content that you can work through at your own pace.', 'Courses', 'Online', 'Free', 'Anyone in the world', 'No registration required for the free lecture notes, exams and videos.', null, false, true, 'https://ocw.mit.edu/', array['science','coding','math']::text[], '2026-10-11'),
('khan', 'Khan Academy', 'Khan Academy', 'A nonprofit offering 840+ free courses in core academic subjects, with apps on the Apple App Store and Google Play.', 'Courses', 'Online', 'Free', 'K-12 and early college', 'For students, teachers and parents.', null, false, true, 'https://www.khanacademy.org/about', array['math','science']::text[], '2026-10-11'),
('kaggle-learn', 'Kaggle Learn', 'Kaggle', 'Short tutorials for building practical data skills, including Python, data visualization and Pandas.', 'Courses', 'Online', 'Free', 'Not stated', 'Not stated', null, false, true, 'https://www.kaggle.com/learn', array['coding']::text[], '2026-10-11'),
('freecodecamp', 'freeCodeCamp', 'freeCodeCamp.org', 'The site describes itself as a place to learn to code for free.', 'Courses', 'Online', 'Free', 'Not stated', 'Not stated', null, false, true, 'https://www.freecodecamp.org/', array['coding']::text[], '2026-10-11'),
('chevening', 'Chevening Scholarships', 'Chevening', 'Fully funded scholarships for outstanding emerging leaders from around the world to study a one-year master’s degree in the UK. What the funding covers is not stated on this page.', 'Scholarships', 'In person', 'Funded', 'One-year master’s degrees in the UK', 'See the official “Who can apply?” page. Eligibility is not listed on the scholarships page.', null, false, true, 'https://www.chevening.org/scholarships/', array['entrepreneurship']::text[], '2026-10-11'),
('fulbright', 'Fulbright Foreign Student Program', 'Fulbright Program', 'Grants that let graduate students, young professionals and artists from abroad study or conduct research in the United States. What the grants cover is not stated on this page.', 'Scholarships', 'In person', 'Funded', 'Graduate students, young professionals and artists from abroad', 'Non-U.S. citizens apply through the Fulbright Commission, Foundation or U.S. Embassy in their home country.', null, false, true, 'https://foreign.fulbrightonline.org/', array['research']::text[], '2026-10-11'),
('daad', 'DAAD Scholarships (Germany)', 'DAAD', 'The German Academic Exchange Service is one of the organizations where international students can apply for a scholarship to study in Germany.', 'Scholarships', 'In person', 'Varies', 'Not stated', 'Levels of study are not stated on this page. Use the DAAD scholarship database to find matching offers.', null, false, true, 'https://www.daad.de/en/study-and-research-in-germany/scholarships/', array['languages']::text[], '2026-10-11'),
('unv', 'United Nations Volunteers', 'UN Volunteers (UNV)', 'A United Nations programme that mobilizes volunteers in 150 countries. The site lists online volunteering as an option.', 'Volunteering', 'Hybrid', 'Not stated', 'Not stated', 'A minimum age is not stated on the homepage. Volunteers register in the Talent Pool. Check the official page for requirements.', null, false, true, 'https://www.unv.org/', array['volunteering']::text[], '2026-10-11'),
('ioi', 'International Olympiad in Informatics (IOI)', 'IOI', 'An international computer science competition. Over two days, students compete individually on programming and algorithmic tasks. UNESCO and IFIP are patrons.', 'Competitions', 'Not stated', 'Not stated', 'Secondary school students (up to four per country)', 'How students qualify is not stated on the homepage. Ask your national olympiad or team.', null, false, true, 'https://ioinformatics.org/', array['coding','math']::text[], '2026-10-11'),
('imo', 'International Mathematical Olympiad (IMO)', 'IMO', 'The official site of the International Mathematical Olympiad. It lists upcoming editions, including IMO 2026 in Shanghai and IMO 2027 in Budapest, Hungary.', 'Competitions', 'Not stated', 'Not stated', 'Not stated', 'Age, school level and how students qualify are not stated on the homepage. Check with your national team.', null, false, true, 'https://www.imo-official.org/', array['math']::text[], '2026-10-11'),
('gsoc', 'Google Summer of Code', 'Google', 'A global online program that brings new contributors into open source software. You work on a 12+ week programming project with an open source organization, guided by mentors.', 'Activities', 'Online', 'Not stated', 'Not stated', 'Age and student status are not stated on the homepage. Check the official eligibility pages before planning on it.', null, false, true, 'https://summerofcode.withgoogle.com/', array['coding']::text[], '2026-10-11'),
('intaward', 'Duke of Edinburgh’s International Award', 'The International Award Foundation', 'A non-formal education framework available in more than 130 countries that recognises achievements outside of school. Participants develop their interests and skills while making a difference in their communities.', 'Activities', 'Not stated', 'Not stated', 'Ages 14 to 24', 'Open to young people aged 14 to 24 regardless of background, location, culture or ability.', null, false, true, 'https://www.intaward.org/', array['volunteering']::text[], '2026-10-11')
